32	
33	        * {
34	            margin: 0;
35	            padding: 0;
36	            box-sizing: border-box;
37	        }
38	
39	        body {
40	            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
41	            line-height: 1.6;
42	            background-color: var(--bg-color);
43	            color: var(--text-color);
44	        }
45	
