67	        .header-container {
68	            max-width: 1200px;
69	            margin: 0 auto;
70	            padding: 0 20px;
71	            display: flex;
72	            justify-content: space-between;
73	            align-items: center;
74	        }
75	
76	        header {
77	            background: var(--primary-gradient);
78	            color: white;
79	            padding: 2rem 20px;
80	            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
81	        }
82	
83	        header h1 {
84	            margin: 0;
85	            font-size: 2.5rem;
86	            font-weight: 600;
87	        }
88	
89	        header nav ul {
90	            list-style: none;
91	            display: flex;
92	            gap: 2rem;
93	            margin: 0;
94	            padding: 0;
95	        }
96	
97	        header nav li a {
98	            color: white;
99	            text-decoration: none;
100	            font-weight: 500;
101	            transition: opacity 0.2s;
102	        }
103	
104	        header nav li a:hover {
105	            opacity: 0.8;
106	        }
107	
108	        header nav li a:focus-visible {
109	            outline: 2px solid white;
110	            outline-offset: 4px;
111	            border-radius: 4px;
112	            padding: 4px 8px;
113	        }
114	
115	        main {
116	            max-width: 1200px;
117	            margin: 0 auto;
118	            padding: 40px 20px;
119	        }
120	
121	        article {
122	            margin-bottom: 3rem;
123	        }
124	
125	        h2 {
126	            color: var(--primary-color);
127	            margin-bottom: 1rem;
128	            font-size: 1.8rem;
129	        }
130	
131	        p {
132	            margin-bottom: 1rem;
133	            font-size: 1.05rem;
134	            line-height: 1.8;
135	        }
136	
137	        .cta-button {
138	            display: inline-block;
139	            background: var(--primary-gradient);
140	            color: white;
141	            padding: 12px 32px;
142	            border: none;
143	            border-radius: 6px;
144	            font-size: 1rem;
145	            cursor: pointer;
146	            text-decoration: none;
147	            transition: transform 0.2s, box-shadow 0.2s;
148	        }
149	
150	        .cta-button:hover {
151	            transform: translateY(-2px);
152	            box-shadow: 0 8px 16px rgba(102, 126, 234, 0.4);
153	        }
154	
155	        .cta-button:active {
156	            transform: translateY(0);
157	        }
158	
159	        .cta-button:focus-visible {
160	            box-shadow: 0 8px 16px rgba(102, 126, 234, 0.4);
161	        }
162	
163	        @media (prefers-reduced-motion: reduce) {
164	            html {
165	                scroll-behavior: auto;
166	            }
167	
168	            * {
169	                animation-duration: 0.01ms !important;
170	                animation-iteration-count: 1 !important;
171	                transition-duration: 0.01ms !important;
172	            }
173	        }
174	
175	        footer {
176	            background-color: #2c3e50;
177	            color: white;
178	            padding: 2rem 20px;
179	            text-align: center;
180	            margin-top: 3rem;
181	        }
182	
