260	</head>
261	<body>
262	    <a href="#main-content" class="skip-link">Skip to main content</a>
263	
264	    <header>
265	        <div class="header-container">
266	            <h1>Welcome</h1>
267	            <nav aria-label="Primary navigation">
268	                <ul>
269	                    <li><a href="#features">Features</a></li>
270	                    <li><a href="#get-started">Get Started</a></li>
271	                </ul>
272	            </nav>
273	        </div>
274	    </header>
275	
276	    <main id="main-content">
277	        <article>
278	            <h2>Modern Web Template</h2>
279	            <p>This is an improved HTML template built with best practices for performance, accessibility, and maintainability.</p>
280	        </article>
281	
282	        <article id="features">
283	            <h2>Key Features</h2>
284	            <p>
285	                This template includes semantic HTML elements, responsive design, modern CSS with gradients,
286	                proper meta tags for SEO, and accessibility considerations to create a solid foundation for any web project.
287	            </p>
288	            <ul class="feature-list">
289	                <li>Semantic HTML5 structure</li>
290	                <li>WCAG 2.1 accessibility compliance</li>
291	                <li>Mobile-first responsive design</li>
292	                <li>Keyboard navigation support</li>
293	                <li>Open Graph meta tags</li>
294	            </ul>
295	        </article>
296	
297	        <article id="get-started">
298	            <h2>Get Started</h2>
299	            <p>
300	                Use this template as a foundation for your next project. It's clean, well-structured, and ready to be
301	                customized to meet your specific needs.
302	            </p>
303	            <button type="button" class="cta-button" aria-label="Learn more about the modern web template">Learn More</button>
304	        </article>
305	    </main>
306	
307	    <footer>
308	        <p>&copy; 2026 Modern Web Template. All rights reserved.</p>
309	        <nav aria-label="Footer links">
310	            <ul>
311	                <li><a href="/privacy/">Privacy Policy</a></li>
312	                <li><a href="/terms/">Terms of Service</a></li>
313	            </ul>
314	        </nav>
315	    </footer>
316	
317	    <script type="application/ld+json">
318	    {
319	        "@context": "https://schema.org",
320	        "@type": "WebSite",
321	        "name": "Modern Web Template",
322	        "description": "A modern, accessible website built with best practices",
323	        "url": "https://example.com/",
324	        "author": {
325	            "@type": "Organization",
326	            "name": "Web Developer"
327	        },
328	        "mainEntity": {
329	            "@type": "CreativeWork",
330	            "name": "Modern Web Template",
331	            "description": "A semantic HTML5 template with accessibility and responsive design"
332	        }
333	    }
334	    </script>
335	
336	    <script>
337	        document.addEventListener('DOMContentLoaded', function() {
338	            const learnMoreBtn = document.querySelector('.cta-button');
339	            if (learnMoreBtn) {
340	                learnMoreBtn.addEventListener('click', function() {
341	                    const featuresSection = document.getElementById('features');
342	                    if (featuresSection) {
343	                        featuresSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
344	                        featuresSection.querySelector('h2').focus();
345	                    }
346	                });
347	            }
348	        });
349	    </script>
350	</body>
351	</html>
